#include "../../models/film_three_finger_resume/ContactRows.h"
#include "../../models/film_rail_tendon/ControlProfile.h"
#include <fstream>
#include <iomanip>
#include <iostream>
using namespace regrip_three_resume;
int main(int argc,char**argv){try{
 if(argc!=3)throw std::runtime_error("checkpoint,output prefix required");std::ifstream in(argv[1]);std::string magic,token;double time,h;unsigned step;in>>magic>>time>>h>>step>>token;SharedFilmSystem s(Layout(),{0,0,-.001},true,true);s.exactUnresolved=true;unsigned n=s.initial.size(),nf=s.shared.nf;Eigen::VectorXd q(n),v(n);for(double&x:q)in>>x;for(double&x:v)in>>x;double unused;for(unsigned i=0;i<4;++i)in>>unused;s.shared.M.setZero();for(unsigned f=0;f<3;++f){auto&m=s.shared.films[f].film;for(unsigned i=0;i<m.mass.size();++i){double mass;in>>mass;m.mass[i]=mass;for(unsigned d=0;d<3;++d){unsigned a=3*i+d;if(m.index[a]>=0)s.shared.M(f*nf+m.index[a],f*nf+m.index[a])+=mass*m.weight[a]*m.weight[a];}}}for(unsigned i=0;i<6;++i)for(unsigned j=0;j<6;++j)in>>s.shared.M(3*nf+i,3*nf+j);if(!in)throw std::runtime_error("checkpoint incomplete");
 std::vector<ContactOwner>old,newborn;for(unsigned f=0;f<3;++f){auto row=s.selected(q,f);old.push_back({f,row.triangle,row.feature});auto other=s.shared.films[f].geometry(s.local(q,f),117);newborn.push_back({f,117,other.feature});}
 auto force=[&](const auto&x,double t){return s.force(x,regrip_film_rail::ControlProfile::evaluate(t,.0001,.01,.02,.03,true).tension);};auto geo=[&](const auto&x){return ownedGeometry(s,x,old);};auto advance=[&](double interval){return regrip_collocation::persistentRows(s.shared.M,2,q,v,time,interval,force,geo);};
 auto initialNew=ownedGeometry(s,q,newborn);auto whole=advance(h);double right=ownedGeometry(s,whole.q,newborn).gap.minCoeff();if(initialNew.gap.minCoeff()<=0||right>=0)throw std::runtime_error("identified117 birth bracket not signed");double lo=0,hi=h;unsigned evaluations=1;
 // Reintegrated endpoint family,NOT interpolation of stored frames/global CCD.
 for(unsigned k=0;k<48&&hi-lo>1e-13;++k){double mid=(lo+hi)/2;auto r=advance(mid);++evaluations;double g=ownedGeometry(s,r.q,newborn).gap.minCoeff();if(g>0)lo=mid;else hi=mid;}
 double eventH=(lo+hi)/2;auto event=advance(eventH);++evaluations;auto ng=ownedGeometry(s,event.q,newborn);if(ng.gap.cwiseAbs().maxCoeff()>1e-10||s.clearance(event.q)<-1e-10)throw std::runtime_error("simultaneous/root whole clearance rejected");
 std::vector<ContactOwner>all=old;all.insert(all.end(),newborn.begin(),newborn.end());auto both=ownedGeometry(s,event.q,all);Eigen::MatrixXd miJ=s.shared.M.ldlt().solve(both.J.transpose()),W=both.J*miJ;Eigen::SelfAdjointEigenSolver<Eigen::MatrixXd>eig(W);if(eig.info()!=Eigen::Success||eig.eigenvalues().minCoeff()<=0)throw std::runtime_error("event rows dependent;no regularization");auto impact=regrip_film_impact::manyRowImpact(s.shared.M,both.J,event.v,1e-10);Eigen::VectorXd vn=both.J*impact.state.velocity;
 std::string prefix=argv[2];std::ofstream rows(prefix+".rows.csv");rows<<std::setprecision(17)<<"row,finger,triangle,feature,gap_mm,pre_normal_velocity_mm_s,post_normal_velocity_mm_s,impulse_Ns,retained\n";std::vector<ContactOwner>active;for(unsigned k=0;k<all.size();++k){bool retained=std::abs(vn(k))<=1e-10;if(retained)active.push_back(all[k]);rows<<k<<','<<all[k].finger<<','<<all[k].triangle<<','<<all[k].feature<<','<<both.gap(k)<<','<<both.J.row(k).dot(event.v)<<','<<vn(k)<<','<<impact.state.impulse(k)<<','<<retained<<'\n';}rows.flush();
 auto result=regrip_collocation::persistentRows(s.shared.M,2,event.q,impact.state.velocity,time+eventH,h-eventH,force,[&](const auto&x){return ownedGeometry(s,x,active);});double gap=s.clearance(result.q);for(const auto&stage:event.stages)gap=std::min(gap,s.clearance(stage.q));for(const auto&stage:result.stages)gap=std::min(gap,s.clearance(stage.q));if(gap< -1e-10)throw std::runtime_error("transfer whole-stage gap fails");std::ofstream report(prefix+".metrics.csv");report<<std::setprecision(17)<<"event_time_s,event_bracket_width_s,new_gap_mm,row_count,active_count,minimum_compliance_eigenvalue,maximum_compliance_eigenvalue,impact_momentum_Ns,impact_energy_loss_Nmm,minimum_stage_gap_mm,endpoint_momentum_Ns,endpoint_normal_velocity_mm_s,root_evaluations\n"<<time+eventH<<','<<hi-lo<<','<<ng.gap.minCoeff()<<','<<all.size()<<','<<active.size()<<','<<eig.eigenvalues().minCoeff()<<','<<eig.eigenvalues().maxCoeff()<<','<<impact.state.momentumResidual<<','<<impact.state.energyLoss<<','<<gap<<','<<result.momentumResidual<<','<<result.velocityResidual<<','<<evaluations<<'\n';std::ofstream state(prefix+".states.txt");state<<std::setprecision(17)<<"EVENT "<<time+eventH<<'\n'<<event.q.transpose()<<'\n'<<event.v.transpose()<<'\n'<<impact.state.velocity.transpose()<<"\nEND "<<time+h<<'\n'<<result.q.transpose()<<'\n'<<result.v.transpose()<<'\n';std::cout<<"PASS isolated identified117 birth/shared impulse/persistent remainder;NOT actual SOFA/global CCD/full-cycle certification\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
